gsap.registerPlugin(ScrollTrigger);
const isMobile = window.innerWidth < 760;

/* cursor */
const cur=document.getElementById('cur'), curR=document.getElementById('curR');
let mx=-100,my=-100,rx=-100,ry=-100;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY});
function cursorLoop(){rx+=(mx-rx)*.12;ry+=(my-ry)*.12;cur.style.transform=`translate(${mx-4}px,${my-4}px)`;curR.style.transform=`translate(${rx-21}px,${ry-21}px)`;requestAnimationFrame(cursorLoop)}cursorLoop();
document.querySelectorAll('a,button,.exp-card,.engine-card,.auto-card').forEach(el=>{el.addEventListener('mouseenter',()=>{cur.style.width='20px';cur.style.height='20px';curR.style.width='66px';curR.style.height='66px';curR.style.borderColor='rgba(0,255,231,.58)'});el.addEventListener('mouseleave',()=>{cur.style.width='8px';cur.style.height='8px';curR.style.width='42px';curR.style.height='42px';curR.style.borderColor='rgba(0,255,231,.32)'})});

/* hero */

const heroWords = gsap.utils.toArray('#heroTitle .hero-word');
gsap.set('#heroTitle',{opacity:1,y:0});
let heroIntroTl;
function playHeroIntro(){
  if(!heroWords.length) return;
  if(heroIntroTl) heroIntroTl.kill();
  gsap.set(heroWords,{yPercent:112,rotateX:-18,opacity:0,filter:'blur(12px)'});
  gsap.set('#heroActions',{opacity:0,y:22,scale:.98});
  gsap.set('#scrollhint',{opacity:0});
  heroIntroTl = gsap.timeline()
    .to(heroWords,{
      yPercent:0,
      rotateX:0,
      opacity:1,
      filter:'blur(0px)',
      duration:.92,
      stagger:.105,
      ease:'expo.out'
    })
    .to('#heroActions',{opacity:1,y:0,scale:1,duration:.58,ease:'power3.out'},'-=.34')
    .to('#scrollhint',{opacity:1,duration:.4},'-=.2');
}
setTimeout(playHeroIntro,160);
ScrollTrigger.create({
  trigger:'#hero',
  start:'top 78%',
  end:'bottom top',
  onEnter:playHeroIntro,
  onEnterBack:playHeroIntro
});
document.querySelector('.logo')?.addEventListener('click',()=>{
  window.scrollTo({top:0,behavior:'smooth'});
  setTimeout(playHeroIntro,520);
});

gsap.to('#hgrid',{y:isMobile?-40:-130,scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('#hcode',{y:isMobile?-35:-90,scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:1.8}});gsap.to('#ho1',{y:isMobile?-45:-160,scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:1.4}});gsap.to('#ho2',{y:isMobile?-35:-120,scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:1.7}});gsap.to('#ho3',{y:isMobile?-28:-95,scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:1.9}});document.querySelectorAll('.hero-badge').forEach((el,i)=>gsap.to(el,{y:`+=${8+i%3*5}`,duration:2.4+i*.22,repeat:-1,yoyo:true,ease:'sine.inOut'}));
ScrollTrigger.create({trigger:'#stats',start:'top 74%',once:true,onEnter:()=>gsap.to('.stat',{opacity:1,y:0,duration:.65,stagger:.09,ease:'power3.out'})});

/* funnel canvas: liquid-glass funnel only, badges are DOM/GSAP controlled */
(function(){
 const canvas=document.getElementById('funnelCanvas');
 if(!canvas) return;
 const ctx=canvas.getContext('2d');
 let W=0,H=0,dpr=1,progress=0,t=0;
 function resize(){
   dpr=Math.min(2,window.devicePixelRatio||1);
   W=canvas.clientWidth; H=canvas.clientHeight;
   canvas.width=W*dpr; canvas.height=H*dpr;
   ctx.setTransform(dpr,0,0,dpr,0,0);
 }
 function draw(){
   t+=0.016;
   ctx.clearRect(0,0,W,H);
   const mobile=W<720;
   const top=mobile?H*.63:H*.64;
   const bot=mobile?H*.95:H*.95;
   const topHalf=mobile?W*.38:Math.min(W*.39,440);
   const botHalf=mobile?Math.max(22,W*.06):Math.max(44,W*.048);

   ctx.save();
   ctx.globalCompositeOperation='lighter';
   const aura=ctx.createRadialGradient(W/2,top,0,W/2,top,W*.48);
   aura.addColorStop(0,'rgba(0,255,231,'+(.08+.20*progress)+')');
   aura.addColorStop(.42,'rgba(123,97,255,'+(.07+.16*progress)+')');
   aura.addColorStop(.82,'rgba(255,45,120,'+(.025+.07*progress)+')');
   aura.addColorStop(1,'transparent');
   ctx.fillStyle=aura; ctx.fillRect(0,0,W,H);
   ctx.restore();

   ctx.save();
   ctx.beginPath();
   ctx.moveTo(W/2-topHalf,top);
   ctx.bezierCurveTo(W/2-topHalf*.88,top+86,W/2-botHalf*1.35,bot-100,W/2-botHalf,bot);
   ctx.lineTo(W/2+botHalf,bot);
   ctx.bezierCurveTo(W/2+botHalf*1.35,bot-100,W/2+topHalf*.88,top+86,W/2+topHalf,top);
   ctx.closePath();

   const body=ctx.createLinearGradient(0,top,0,bot);
   body.addColorStop(0,'rgba(28,34,62,.78)');
   body.addColorStop(.18,'rgba(255,255,255,.075)');
   body.addColorStop(.52,'rgba(7,10,22,.84)');
   body.addColorStop(1,'rgba(0,0,0,.96)');
   ctx.fillStyle=body; ctx.fill();
   ctx.lineWidth=1.6; ctx.strokeStyle='rgba(255,255,255,'+(.10+.08*progress)+')'; ctx.stroke();
   ctx.clip();

   const glass=ctx.createLinearGradient(W/2-topHalf,top,W/2+topHalf,bot);
   glass.addColorStop(0,'rgba(255,255,255,.22)');
   glass.addColorStop(.20,'rgba(255,255,255,.028)');
   glass.addColorStop(.56,'rgba(0,255,231,.055)');
   glass.addColorStop(.82,'rgba(123,97,255,.035)');
   glass.addColorStop(1,'rgba(255,255,255,.018)');
   ctx.fillStyle=glass; ctx.fillRect(W/2-topHalf,top,topHalf*2,bot-top);

   for(let i=0;i<10;i++){
     const yy=top+((t*42+i*64)%(bot-top));
     ctx.beginPath();
     ctx.moveTo(W/2-topHalf*.72,yy);
     ctx.bezierCurveTo(W/2-topHalf*.22,yy+18,W/2+topHalf*.22,yy-18,W/2+topHalf*.72,yy);
     ctx.strokeStyle='rgba(255,255,255,'+(.025+progress*.08)+')';
     ctx.lineWidth=1; ctx.stroke();
   }
   ctx.restore();

   ctx.save();
   ctx.shadowBlur=50+progress*50;
   ctx.shadowColor='rgba(0,255,231,.92)';
   ctx.beginPath();
   ctx.ellipse(W/2,top,topHalf*1.08,30,0,0,Math.PI*2);
   const rim=ctx.createLinearGradient(W/2-topHalf,top,W/2+topHalf,top);
   rim.addColorStop(0,'rgba(0,255,231,.10)');
   rim.addColorStop(.18,'rgba(0,255,231,.98)');
   rim.addColorStop(.48,'rgba(74,163,255,.82)');
   rim.addColorStop(.68,'rgba(123,97,255,.94)');
   rim.addColorStop(.85,'rgba(255,45,120,.78)');
   rim.addColorStop(1,'rgba(0,255,231,.10)');
   ctx.strokeStyle=rim; ctx.lineWidth=3.2; ctx.stroke();
   ctx.restore();

   ctx.save();
   ctx.globalCompositeOperation='lighter';
   for(let i=0;i<18;i++){
     const py=top+((t*65+i*39)%(bot-top));
     const amp=(1-Math.min(1,(py-top)/(bot-top)))*topHalf*.68+botHalf*.3;
     ctx.beginPath();
     ctx.arc(W/2+Math.sin(t*2.6+i)*amp*.19,py,1.4+progress*2.3,0,Math.PI*2);
     ctx.fillStyle='rgba(0,255,231,'+(.055+progress*.30)+')';
     ctx.fill();
   }
   ctx.restore();

   requestAnimationFrame(draw);
 }
 resize();
 window.addEventListener('resize',resize,{passive:true});
 ScrollTrigger.create({
   trigger:'#funnel',
   start:'top top',
   end:'bottom bottom',
   scrub:true,
   onUpdate:self=>{
     progress=self.progress;
     const out=document.getElementById('funnelOutput');
     if(out){
       const o=Math.max(0,(progress-.72)*3.2);
       out.style.opacity=o;
       out.style.transform='translateX(-50%) translateY('+(20-o*20)+'px) scale('+(0.96+o*.08)+')';
     }
   }
 });
 draw();
})();

